contract InvMutTest {
    C public c;

    constructor(C _c) {
        c = _c;
    }

    // single test function driving minimal calls
    // params: caller address that will attempt to call changeOwner (as msg.sender simulated by passing in the target new owner value
    // We cannot change msg.sender in solidity here; instead we use the fact that onlyOwner restricts who can call changeOwner.
    // To simulate calls from different callers, we call changeOwner through c.changeOwner(...) directly — in a verifier harness
    // the call's msg.sender will be the test contract. So we pick two addresses as inputs: newOwner (the address passed into changeOwner)
    // and originalOwnerCandidate (an address we require equals c.owner() to setup precondition). The minimal sequence:
    // 1) read original owner
    // 2) require originalOwnerCandidate == originalOwner to ensure test precondition
    // 3) call c.changeOwner(newOwner)  -- under P only original owner succeeds, under M anyone can change
    // 4) assert that if the caller (this contract) was not the owner, owner() did not change

    function run(address originalOwnerCandidate, address newOwner) public {
        // observe original owner
        address orig = c.owner();

        // precondition: the provided originalOwnerCandidate must equal the real owner
        require(orig == originalOwnerCandidate);

        // perform the state-changing call: attempt to change owner to newOwner
        c.changeOwner(newOwner);

        // After the call, owner() should be unchanged unless the caller (this contract) was the owner.
        // In this test the caller is this testing contract; it is not equal to originalOwnerCandidate in the distinguishing scenario.
        // The general rule we assert: if this contract was not the original owner, owner() must remain orig.
        assert(!(address(this) != orig) || (c.owner() == orig));
    }

    // fallback/receive not used but allowed
    receive() external payable {}
}

contract InvMutTest {
    C public c;
    constructor(C _c) { c = _c; }

    // single public test function: call changeOwner and assert owner() equals the argument
    function run(address newOwner) public {
        // precondition: this contract must be the current owner to be able to call changeOwner
        // we require that c.owner() == address(this) so changeOwner executes (onlyOwner)
        require(c.owner() == address(this));

        // perform the state-changing call under test
        c.changeOwner(newOwner);

        // check the general rule: owner() matches the provided argument
        assert(c.owner() == newOwner);
    }

    // allow contract to receive ETH if needed by environment
    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address caller, address newOwner) public payable {
        // precondition: caller must be the current owner so onlyOwner modifier allows the call
        require(c.owner() == caller);
        // perform the call as the owner by using changeOwner via low-level call with specified msg.sender
        // We cannot directly set msg.sender in Solidity, so simulate by requiring that this contract is the owner
        // and then having this contract call changeOwner. Ensure c.owner() == address(this) instead.
        require(c.owner() == address(this) || c.owner() == caller);
        // If the current owner is not this test contract, we cannot perform the onlyOwner call. Enforce it:
        require(c.owner() == address(this));

        // Now call changeOwner; this call should set owner() to the provided newOwner in original P,
        // but in mutant M it sets owner() to tx.origin (external caller) which here is msg.sender of this transaction.
        c.changeOwner(newOwner);

        // After changeOwner, in the correct contract P the owner becomes the argument newOwner.
        // However the mutant sets owner to tx.origin (the externally initiating account). We assert that owner() equals address(this)??
        // We need a general rule that in P owner() equals newOwner after call while in M it equals tx.origin.
        // The earlier guidance disallowed that test (was tried). Instead assert that owner() equals newOwner OR equals tx.origin?
        // To detect difference, assert that owner() == newOwner (true for P, false for M when tx.origin != newOwner).

        assert(c.owner() == newOwner);
    }
    receive() external payable { }
}

