contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }
    function run(address newOwner, address spender) public payable {
        // precondition: the test caller must be the current owner of c
        require(c.owner() == msg.sender);
        // make an external (non-state-changing) call that will appear in tx.origin chain
        c.allowance(msg.sender, spender);
        // now call changeOwner as the owner; in the original contract this will set owner to newOwner (the param)
        c.changeOwner(newOwner);
        // assert that owner was set to the immediate caller (msg.sender) rather than to tx.origin via mutant;
        // because msg.sender is the owner and invoked changeOwner, owner() must equal newOwner (the provided argument)
        assert(keccak256(abi.encodePacked(c.owner())) == keccak256(abi.encodePacked(newOwner)));
    }
    receive() external payable { }
