pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameters: two addresses to pass to allowance; the general property
    // is that calling the view allowance(...) does not change the owner.
    function testFuzz_property(address a, address b) public {
        // keep addresses wide but avoid zero address because some ERC20 implementers may revert on zero in other contexts
        vm.assume(a != address(0));
        vm.assume(b != address(0));

        // record owner before calling allowance
        address before = c.owner();

        // call allowance (a view). Use try/catch to tolerate any unexpected reverts
        bool ok;
        try c.allowance(a, b) returns (uint256) {
            ok = true;
        } catch {
            ok = true; // even if it reverts, the correct contract must not change owner; we treat revert as allowed but still owner must be unchanged
        }

        // exactly one assertion: owner must remain equal to before for the correct contract for all inputs
        assertTrue(c.owner() == before);
    }
}

