pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(address(this), address(this)); }

    // Fuzzed parameter: an arbitrary address attacker that will be used as tx.origin by performing a call
    // through a helper contract. The property: calling allowance(...) (a view) and making an external caller
    // interact with c must never change c.owner() in the reference implementation; the mutant may change it
    // by using tx.origin in changeOwner called during such an external interaction.
    function testFuzz_property(address attacker) public {
        // avoid zero address for clarity
        vm.assume(attacker != address(0));
        // ensure attacker has some ETH to make calls if needed
        vm.deal(attacker, 1 ether);

        // Deploy a helper that will call c.changeOwner(...) via a direct call from attacker as tx.origin.
        // The helper will forward a call to c.changeOwner(attacker), so for the reference contract only the
        // owner (set in constructor to address(this) i.e. this test contract) can call changeOwner; hence
        // the forwarded call should revert due to onlyOwner — and thus should not change owner.
        // For the mutant, if changeOwner uses tx.origin instead of the provided argument, and if the helper
        // is invoked in a way that causes the contract to accept the forwarded call as from the owner path,
        // the mutant may change owner to tx.origin. We create a Helper that will try to invoke changeOwner
        // as if it were the owner by relying on being called by this test (which is the owner) but with
        // tx.origin == attacker when attacker initiates the top-level transaction; this distinguishes ref vs mutant.

        MaliciousHelper helper = new MaliciousHelper(c);

        // record owner before interaction
        address ownerBefore = c.owner();

        // Now have attacker call the helper. The helper's function will use msg.sender (the helper's caller)
        // as the immediate caller to c.changeOwner but tx.origin will be attacker. The reference contract
        // changeOwner requires onlyOwner (ownerBefore == msg.sender). The helper will perform the call using
        // a call that sets msg.sender to the helper (so msg.sender != ownerBefore) and thus should revert in
        // the reference; the mutant changes _owner to tx.origin inside changeOwner if it is executed, which
        // would set owner to attacker. We arrange the call so the helper first tries to call allowance(...) on c
        // (a view) and then invokes changeOwner through the helper's own function. The observable difference
        // is that owner remains ownerBefore for the reference for all inputs, but for some attacker addresses
        // the mutant will end up setting owner to attacker.

        // The test executes a transaction with tx.origin == attacker calling helper.runSequence();
        vm.prank(attacker);
        helper.runSequence();

        address ownerAfter = c.owner();

        // The universal property: after performing the above interaction (which includes calling allowance via helper
        // and attempting to change owner), the owner must remain unchanged in the reference implementation. The buggy
        // mutant that assigns _owner = tx.origin inside changeOwner can be made to change owner to attacker for some
        // attacker values; thus for the reference the owner stays equal to ownerBefore for all attacker inputs.
        assertTrue(ownerAfter == ownerBefore);
    }
}

// Minimal helper that first calls allowance (a view) then attempts to invoke changeOwner on the target contract.
contract MaliciousHelper {
    C public target;
    constructor(C _target) {
        target = _target;
    }

    // Called by attacker (so tx.origin == attacker). This function calls target.allowance(...) then calls changeOwner
    // by making an external call to target.changeOwner(address(this)) so that msg.sender when changeOwner runs is this helper.
    // In the reference, onlyOwner modifier will check that msg.sender == owner (owner was set to the test contract in ctor),
    // which will fail and revert; in the mutant, if changeOwner uses tx.origin it may set owner to attacker.
    function runSequence() external {
        // call a view allowance to exercise the path described; it should not mutate owner in reference
        // we call with arbitrary addresses
        target.allowance(address(1), address(2));

        // Now attempt to become owner by calling changeOwner on target; pass some address (ignored by mutant)
        // We call changeOwner with address(this) so that msg.sender != original owner and onlyOwner should revert in reference.
        // If mutant sets _owner = tx.origin inside changeOwner and the call is not prevented, owner becomes tx.origin (attacker).
        // Use a low-level call to avoid bubbling revert details; we still let it revert if it does.
        (bool ok, ) = address(target).call(abi.encodeWithSignature("changeOwner(address)", address(this)));
        // ignore ok; test observes owner on-chain
        ok; // silence unused warning
    }
}

