pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(address(this), address(this)); }

    // The fuzzer will supply an arbitrary address 'actor' and an arbitrary bool 'callChangeOwner'
    // We use 'callChangeOwner' to decide whether to invoke changeOwner via an adversarial intermediary
    // so tx.origin differs from msg.sender when changeOwner is executed.
    function testFuzz_property(address actor, bool callChangeOwner) public {
        // Keep actor non-zero to be meaningful
        vm.assume(actor != address(0));

        // Record owner before any interactions
        address ownerBefore = c.owner();

        // Always call the view allowance (should not mutate state in reference)
        // Use arbitrary addresses for allowance call (fuzzable via 'actor' and this contract)
        // We call as different msg.sender to ensure coverage of different call contexts
        // Use try/catch to ensure we don't revert (allowance is view and should not revert)
        bool ok;
        try c.allowance(actor, address(this)) returns (uint256) {
            ok = true;
        } catch {
            ok = false;
        }
        // Ensure the call itself succeeded (it should on the reference and mutant)
        // but we don't enforce it as the distinguishing property; still, abort meaningless cases
        vm.assume(ok);

        // Optionally, if callChangeOwner is true, arrange for an external call that will cause changeOwner
        // to be invoked with tx.origin == actor. To do that we deploy a small helper that calls c.changeOwner
        // in a context where msg.sender is the helper but tx.origin is actor.
        if (callChangeOwner) {
            // Fund the actor so it can perform the call
            vm.deal(actor, 1 ether);
            // Deploy helper
            Helper h = new Helper();
            // Prank as actor so tx.origin == actor
            vm.prank(actor);
            // Have helper call changeOwner on c, passing some address (we let it pass actor as argument)
            h.callChangeOwner(address(c), actor);
        }

        // After allowance() and optional external sequence, owner must remain unchanged in reference
        address ownerAfter = c.owner();

        // Single assertion: the contract owner did not change after these interactions
        assertTrue(ownerAfter == ownerBefore);
    }
}

// Minimal helper that calls changeOwner on target
contract Helper {
    function callChangeOwner(address target, address newOwner) external {
        C(target).changeOwner(newOwner);
    }
}
